1600|     CAMLassert (!Has_status_hd(hd, caml_global_heap_state.GARBAGE));
1601|     s->allocated += Wsize_bsize(LARGE_ALLOC_HEADER_SZ) + Whsize_hd(hd);
1602|     s->overhead += Wsize_bsize(LARGE_ALLOC_HEADER_SZ);
